172	  std::string ToolPath = llvm::sys::fs::getMainExecutable(argv[0], nullptr);
173	
174	  // Initialize targets and assembly printers/parsers.
175	#define BOLT_TARGET(target)                                                    \
176	  LLVMInitialize##target##TargetInfo();                                        \
177	  LLVMInitialize##target##TargetMC();                                          \
178	  LLVMInitialize##target##AsmParser();                                         \
179	  LLVMInitialize##target##Disassembler();                                      \
180	  LLVMInitialize##target##Target();                                            \
181	  LLVMInitialize##target##AsmPrinter();
182	
183	#include "bolt/Core/TargetConfig.def"
