185	  ToolName = argv[0];
186	
187	  if (llvm::sys::path::filename(ToolName).starts_with("perf2bolt"))
188	    perf2boltMode(argc, argv);
189	  else if (llvm::sys::path::filename(ToolName).starts_with("llvm-boltdiff"))
190	    boltDiffMode(argc, argv);
191	  else
192	    boltMode(argc, argv);
193	
194	  if (!sys::fs::exists(opts::InputFilename))
195	    report_error(opts::InputFilename, errc::no_such_file_or_directory);
196	
197	  // Initialize journaling streams
198	  raw_ostream *BOLTJournalOut = &outs();
199	  raw_ostream *BOLTJournalErr = &errs();
200	  // RAII obj to keep log file open throughout execution
201	  std::unique_ptr<raw_fd_ostream> LogFileStream;
202	  if (!opts::LogFile.empty()) {
203	    std::error_code LogEC;
204	    LogFileStream = std::make_unique<raw_fd_ostream>(
205	        opts::LogFile, LogEC, sys::fs::OpenFlags::OF_None);
206	    if (LogEC) {
207	      errs() << "BOLT-ERROR: cannot open requested log file for writing: "
208	             << LogEC.message() << "\n";
209	      exit(1);
210	    }
211	    BOLTJournalOut = LogFileStream.get();
212	    BOLTJournalErr = LogFileStream.get();
213	  }
214	
215	  // Attempt to open the binary.
216	  if (!opts::DiffOnly) {
217	    Expected<OwningBinary<Binary>> BinaryOrErr =
218	        createBinary(opts::InputFilename);
219	    if (Error E = BinaryOrErr.takeError())
220	      report_error(opts::InputFilename, std::move(E));
221	    Binary &Binary = *BinaryOrErr.get().getBinary();
222	
223	    if (auto *e = dyn_cast<ELFObjectFileBase>(&Binary)) {
224	      auto RIOrErr = RewriteInstance::create(e, argc, argv, ToolPath,
225	                                             *BOLTJournalOut, *BOLTJournalErr);
226	      if (Error E = RIOrErr.takeError())
227	        report_error(opts::InputFilename, std::move(E));
228	      RewriteInstance &RI = *RIOrErr.get();
229	
230	      if (opts::AggregateOnly && !RI.getBinaryContext().isAArch64() &&
231	          opts::ArmSPE) {
232	        errs() << ToolName << ": -spe is available only on AArch64.\n";
233	        exit(1);
234	      }
235	
236	      if (!opts::PerfData.empty()) {
237	        for (StringRef Filename : opts::PerfData)
238	          if (Error E = RI.setProfile(Filename))
239	            report_error(Filename, std::move(E));
240	      } else if (opts::AggregateOnly) {
241	        errs() << ToolName << ": missing required -perfdata option.\n";
242	        exit(1);
243	      }
244	      if (!opts::InputDataFilename.empty()) {
245	        if (Error E = RI.setProfile(opts::InputDataFilename))
246	          report_error(opts::InputDataFilename, std::move(E));
247	      }
248	
249	      if (Error E = RI.run())
250	        report_error(opts::InputFilename, std::move(E));
251	    } else if (auto *O = dyn_cast<MachOObjectFile>(&Binary)) {
252	      auto MachORIOrErr = MachORewriteInstance::create(O, ToolPath);
253	      if (Error E = MachORIOrErr.takeError())
254	        report_error(opts::InputFilename, std::move(E));
255	      MachORewriteInstance &MachORI = *MachORIOrErr.get();
256	
257	      if (!opts::InputDataFilename.empty())
258	        if (Error E = MachORI.setProfile(opts::InputDataFilename))
259	          report_error(opts::InputDataFilename, std::move(E));
260	
261	      MachORI.run();
262	    } else {
263	      report_error(opts::InputFilename, object_error::invalid_file_type);
264	    }
265	
266	    return EXIT_SUCCESS;
267	  }
268	
269	  // Bolt-diff
270	  Expected<OwningBinary<Binary>> BinaryOrErr1 =
271	      createBinary(opts::InputFilename);
272	  Expected<OwningBinary<Binary>> BinaryOrErr2 =
273	      createBinary(opts::InputFilename2);
274	  if (Error E = BinaryOrErr1.takeError())
275	    report_error(opts::InputFilename, std::move(E));
276	  if (Error E = BinaryOrErr2.takeError())
277	    report_error(opts::InputFilename2, std::move(E));
278	  Binary &Binary1 = *BinaryOrErr1.get().getBinary();
279	  Binary &Binary2 = *BinaryOrErr2.get().getBinary();
280	  if (auto *ELFObj1 = dyn_cast<ELFObjectFileBase>(&Binary1)) {
281	    if (auto *ELFObj2 = dyn_cast<ELFObjectFileBase>(&Binary2)) {
282	      auto RI1OrErr = RewriteInstance::create(ELFObj1, argc, argv, ToolPath);
283	      if (Error E = RI1OrErr.takeError())
284	        report_error(opts::InputFilename, std::move(E));
285	      RewriteInstance &RI1 = *RI1OrErr.get();
286	      if (Error E = RI1.setProfile(opts::InputDataFilename))
287	        report_error(opts::InputDataFilename, std::move(E));
288	      auto RI2OrErr = RewriteInstance::create(ELFObj2, argc, argv, ToolPath);
289	      if (Error E = RI2OrErr.takeError())
290	        report_error(opts::InputFilename2, std::move(E));
291	      RewriteInstance &RI2 = *RI2OrErr.get();
292	      if (Error E = RI2.setProfile(opts::InputDataFilename2))
293	        report_error(opts::InputDataFilename2, std::move(E));
294	      outs() << "BOLT-DIFF: *** Analyzing binary 1: " << opts::InputFilename
295	             << "\n";
296	      outs() << "BOLT-DIFF: *** Binary 1 fdata:     " << opts::InputDataFilename
297	             << "\n";
298	      if (Error E = RI1.run())
299	        report_error(opts::InputFilename, std::move(E));
300	      outs() << "BOLT-DIFF: *** Analyzing binary 2: " << opts::InputFilename2
301	             << "\n";
302	      outs() << "BOLT-DIFF: *** Binary 2 fdata:     "
303	             << opts::InputDataFilename2 << "\n";
304	      if (Error E = RI2.run())
305	        report_error(opts::InputFilename2, std::move(E));
306	      RI1.compare(RI2);
307	    } else {
308	      report_error(opts::InputFilename2, object_error::invalid_file_type);
309	    }
310	  } else {
311	    report_error(opts::InputFilename, object_error::invalid_file_type);
312	  }
313	
314	  return EXIT_SUCCESS;
315	}
