307	Error BinaryFunctionPassManager::runPasses() {
308	  auto &BFs = BC.getBinaryFunctions();
309	  for (size_t PassIdx = 0; PassIdx < Passes.size(); PassIdx++) {
310	    const std::pair<const bool, std::unique_ptr<BinaryFunctionPass>>
311	        &OptPassPair = Passes[PassIdx];
312	    if (!OptPassPair.first)
313	      continue;
314	
315	    const std::unique_ptr<BinaryFunctionPass> &Pass = OptPassPair.second;
316	    std::string PassIdName =
317	        formatv("{0:2}_{1}", PassIdx, Pass->getName()).str();
318	
319	    if (opts::Verbosity > 0)
320	      BC.outs() << "BOLT-INFO: Starting pass: " << Pass->getName() << "\n";
321	
322	    NamedRegionTimer T(Pass->getName(), Pass->getName(), TimerGroupName,
323	                       TimerGroupDesc, TimeOpts);
324	
325	    Error E = Error::success();
326	    callWithDynoStats(
327	        BC.outs(),
328	        [this, &E, &Pass] {
329	          E = joinErrors(std::move(E), Pass->runOnFunctions(BC));
330	        },
331	        BFs, Pass->getName(), opts::DynoStatsAll, BC.isAArch64());
332	    if (E)
333	      return Error(std::move(E));
334	
335	    if (opts::VerifyCFG &&
336	        !std::accumulate(
337	            BFs.begin(), BFs.end(), true,
338	            [](const bool Valid,
339	               const std::pair<const uint64_t, BinaryFunction> &It) {
340	              return Valid && It.second.validateCFG();
341	            })) {
342	      return createFatalBOLTError(
343	          Twine("BOLT-ERROR: Invalid CFG detected after pass ") +
344	          Twine(Pass->getName()) + Twine("\n"));
345	    }
346	
347	    if (opts::Verbosity > 0)
348	      BC.outs() << "BOLT-INFO: Finished pass: " << Pass->getName() << "\n";
349	
350	    if (!opts::PrintAll && !opts::DumpDotAll && !Pass->printPass())
351	      continue;
352	
353	    const std::string Message = std::string("after ") + Pass->getName();
354	
355	    for (auto &It : BFs) {
356	      BinaryFunction &Function = It.second;
357	
358	      if (!Pass->shouldPrint(Function))
359	        continue;
360	
361	      Function.print(BC.outs(), Message);
362	
363	      if (opts::shouldDumpDot(Function))
364	        Function.dumpGraphForPass(PassIdName);
365	    }
366	  }
367	  return Error::success();
368	}
